Same as: https://github.com/jimmya/sourcery-templates/pull/37 but now for methods.

```swift
public protocol CoolProtocol: Actor {
    nonisolated func getSomething() -> String { get }
}
```

Will generate:

```swift
public actor MockCoolProtocol: CoolProtocol {

    public var invokedGetSomething: Bool { invokedGetSomethingCount > 0 }
    public nonisolated(unsafe) var invokedGetSomethingCount = 0
    public nonisolated(unsafe) var stubbedGetSomethingResult: String!
    public nonisolated(unsafe) var invokedGetSomethingExpectation = XCTestExpectation(description: "\(#function) expectation")
    public nonisolated(unsafe) var invokedGetSomethingContinuation: CheckedContinuation<(), Never>?

    public nonisolated func getSomething() -> String {
        defer {
            invokedGetSomethingExpectation.fulfill()
            invokedGetSomethingContinuation?.resume()
        }
        invokedGetSomethingCount += 1
        return stubbedGetSomethingResult
    }
}
```

